/**
 * @param {string} encodedText
 * @param {number} rows
 * @return {string}
 */
var decodeCiphertext = function(encodedText, rows) {
    const m = rows;
    const n = encodedText.length / rows;

    const arr = encodedText.split('');
    const mat = [];

    for (let i = 0; i < encodedText.length; i += n) {
        mat.push(arr.slice(i, i + n));
    }

    let res = '';

    for (let startCol = 0; startCol < n; startCol++) {
        let row = 0;
        let col = startCol;

        while (row < m && col < n) {
            res += mat[row][col];
            row++;
            col++;
        }
    }

    return res.trimEnd();
};
